#!/usr/bin/env bash
set -euo pipefail
BASE="/opt/epimediahub/provisioning"
PY="$BASE/.venv/bin/python"
TARGET="$BASE/skip_detector_v3.py"
TMP="$(mktemp /tmp/skip_detector_v3.XXXXXX.py)"
trap 'rm -f "$TMP"' EXIT
if [ ! -x "$PY" ]; then echo "FEHLER: Python-Venv nicht gefunden: $PY" >&2; exit 1; fi
if ! "$PY" -c 'import numpy' >/dev/null 2>&1; then
  echo "=== NumPy fehlt – wird automatisch in der EpiMediaHub-Venv installiert ==="
  if ! "$PY" -m pip --version >/dev/null 2>&1; then
    "$PY" -m ensurepip --upgrade
  fi
  "$PY" -m pip install --disable-pip-version-check --no-cache-dir "numpy>=1.26,<3"
  "$PY" -c 'import numpy as np; print("NumPy OK:", np.__version__)'
fi
for exe in ffmpeg fpcalc; do
  if ! command -v "$exe" >/dev/null 2>&1; then
    echo "FEHLER: $exe fehlt." >&2
    [ "$exe" != "fpcalc" ] || echo "Debian/Raspberry Pi: Paket libchromaprint-tools" >&2
    exit 1
  fi
done
PAYLOAD=''
printf '%s' "$PAYLOAD" | base64 -d | gzip -d > "$TMP"
chmod 0644 "$TMP"
echo "=== 1/5 Syntax ==="; "$PY" -m py_compile "$TMP"
echo "=== 2/5 Selbsttest ==="; "$PY" "$TMP" --selftest
echo "=== 3/5 Doctor ==="; "$PY" "$TMP" --doctor
echo "=== 4/5 Echter ffmpeg/fpcalc E2E-Test ==="; "$PY" "$TMP" --e2e
echo "=== 5/5 Installation ==="
if [ -f "$TARGET" ]; then BACKUP="$TARGET.bak-$(date +%Y%m%d-%H%M%S)"; cp -a "$TARGET" "$BACKUP"; echo "Backup: $BACKUP"; fi
install -o root -g root -m 0644 "$TMP" "$TARGET"
echo; echo "Installiert: $TARGET"; "$PY" "$TARGET" --timebase; ls -lh "$TARGET"
echo; echo "V3.1 ist installiert und getestet. skip_analysis_worker.py wurde NICHT veraendert."
